#include <algorithm>
#include <cmath>
#include <vector>

double american_put(double s, double k, double r, double sigma, double t, int n) {
    double dt = t / n;
    double u = std::exp(sigma * std::sqrt(dt)), d = 1 / u;
    double growth = std::exp(r * dt);
    double q = (growth - d) / (u - d), disc = 1 / growth;
    std::vector<double> v(n + 1);
    double node = s * std::pow(d, n);   // price at (n, 0): all downs
    for (int j = 0; j <= n; ++j) {
        v[j] = std::max(k - node, 0.0);
        node *= u * u;                  // one more up, one fewer down
    }
    for (int i = n - 1; i >= 0; --i) {
        node = s * std::pow(d, i);      // one pow per step, not per node
        for (int j = 0; j <= i; ++j) {
            double hold = disc * (q * v[j + 1] + (1 - q) * v[j]);
            v[j] = std::max(hold, k - node);
            node *= u * u;
        }
    }
    return v[0];
}

