widget.prelude:
#include <algorithm>
#include <cmath>
#include <vector>

struct Payoff {
    virtual ~Payoff() = default;
    virtual double operator()(double s) const = 0;
};

struct CallPayoff : Payoff {
    double k;
    explicit CallPayoff(double k) : k(k) {}
    double operator()(double s) const override { return std::max(s - k, 0.0); }
};

struct PutPayoff : Payoff {
    double k;
    explicit PutPayoff(double k) : k(k) {}
    double operator()(double s) const override { return std::max(k - s, 0.0); }
};

long long zq_trees = 0;

// Level 2's pricer: one row of n + 1 values, reused at every step.
double binomial_price(const Payoff& payoff, double s, double r, double sigma,
                      double t, int n, bool american) {
    ++zq_trees;
    double dt = t / n;
    double u = std::exp(sigma * std::sqrt(dt)), d = 1 / u;
    double growth = std::exp(r * dt);
    double q = (growth - d) / (u - d), disc = 1 / growth;
    std::vector<double> v(n + 1);
    for (int j = 0; j <= n; ++j)
        v[j] = payoff(s * std::pow(u, j) * std::pow(d, n - j));
    for (int i = n - 1; i >= 0; --i)
        for (int j = 0; j <= i; ++j) {
            v[j] = disc * (q * v[j + 1] + (1 - q) * v[j]);
            if (american)
                v[j] = std::max(v[j], payoff(s * std::pow(u, j) * std::pow(d, i - j)));
        }
    return v[0];
}

